('Asia-Pacific Market Entry', 'Mercados China, Índia, Japão e Sudeste Asiático.', 'international_market', ARRAY['China', 'India', 'Japan', 'Asia', 'market_entry'], true, 'active', 0.84),
('Middle East & Africa Operations', 'Mercados emergentes: Saudi Vision 2030, UAE, África do Sul.', 'international_market', ARRAY['Middle_East', 'Africa', 'Saudi_Arabia', 'UAE'], true, 'active', 0.83),
('Industry 4.0 Smart Factory', 'Industry 4.0 em reciclagem: IoT, digital twin, visão computacional.', 'recycling_technology', ARRAY['Industry_4.0', 'IoT', 'smart_factory', 'AI'], true, 'active', 0.91);
